// Recebe os dados do endereço
const rua = $input.item.json.rua || '';
const numero = $input.item.json.numero || '';
const bairro = $input.item.json.bairro || '';
const cidade = 'Montes Claros';
const estado = 'MG';
const pais = 'Brasil';

// Validação básica
if (!rua || !numero || !bairro) {
  return {
    sucesso: false,
    erro: 'Dados incompletos. Envie: rua, numero e bairro',
    mensagem: 'Por favor, informe o endereço completo: rua, número e bairro'
  };
}

// Monta o endereço completo para geocoding
const enderecoCompleto = `${rua}, ${numero}, ${bairro}, ${cidade}, ${estado}, ${pais}`;

// Retorna os dados processados
return {
  endereco_completo: enderecoCompleto,
  endereco_formatado: `${rua}, ${numero} - ${bairro}, ${cidade}/${estado}`,
  rua: rua.trim(),
  numero: numero.toString().trim(),
  bairro: bairro.trim(),
  cidade,
  estado,
  validado: true
};

// Pega os dados do node anterior
const input = $input.item.json;
const validacaoNode = $('Validar Endereço').item.json;

// Verifica se encontrou coordenadas
if (!input || !Array.isArray(input) || input.length === 0) {
  return {
    sucesso: false,
    erro: 'Endereço não encontrado',
    mensagem: 'Não foi possível encontrar as coordenadas deste endereço. Verifique se o endereço está correto.',
    endereco_fornecido: validacaoNode.endereco_formatado
  };
}

// Pega as coordenadas encontradas
const resultado = input[0];
const latitudeCliente = parseFloat(resultado.lat);
const longitudeCliente = parseFloat(resultado.lon);

// ⚙️ CONFIGURE AQUI AS COORDENADAS DA SUA LOJA/ORIGEM
// Coordenadas padrão: Centro de Montes Claros, MG
const ORIGEM_LATITUDE = -16.7285;  // ← ALTERE AQUI
const ORIGEM_LONGITUDE = -43.8621; // ← ALTERE AQUI

// Função Haversine para calcular distância entre dois pontos
function calcularDistancia(lat1, lon1, lat2, lon2) {
  const R = 6371; // Raio da Terra em km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;

  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon/2) * Math.sin(dLon/2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  const distancia = R * c;

  return distancia;
}

// Calcula a distância
const distanciaKm = calcularDistancia(
  ORIGEM_LATITUDE,
  ORIGEM_LONGITUDE,
  latitudeCliente,
  longitudeCliente
);

// Retorna os dados com as coordenadas e distância
return {
  ...validacaoNode,
  latitude: latitudeCliente,
  longitude: longitudeCliente,
  distancia_km: parseFloat(distanciaKm.toFixed(2)),
  origem_lat: ORIGEM_LATITUDE,
  origem_lng: ORIGEM_LONGITUDE,
  endereco_geocodificado: resultado.display_name
};

// Pega os dados do node anterior
const item = $input.item.json;

// Se houve erro, retorna
if (item.sucesso === false) {
  return item;
}

const distanciaKm = item.distancia_km;

// ⚙️ TABELA DE PREÇOS POR DISTÂNCIA (RAIO)
// VOCÊ PODE CUSTOMIZAR OS VALORES E AS FAIXAS
const tabelaFretePorDistancia = [
  { ate_km: 2, valor: 10.00, descricao: 'Até 2 km' },
  { ate_km: 5, valor: 15.00, descricao: '2 a 5 km' },
  { ate_km: 8, valor: 20.00, descricao: '5 a 8 km' },
  { ate_km: 12, valor: 25.00, descricao: '8 a 12 km' },
  { ate_km: 15, valor: 30.00, descricao: '12 a 15 km' },
  { ate_km: 20, valor: 35.00, descricao: '15 a 20 km' },
  { ate_km: 999, valor: 40.00, descricao: 'Acima de 20 km' }
];

// Encontra o valor do frete baseado na distância
let valorFrete = 40.00; // Valor padrão
let faixaDescricao = 'Acima de 20 km';

for (const faixa of tabelaFretePorDistancia) {
  if (distanciaKm <= faixa.ate_km) {
    valorFrete = faixa.valor;
    faixaDescricao = faixa.descricao;
    break;
  }
}

// Retorna o resultado completo
return {
  sucesso: true,
  mensagem: `Frete calculado com sucesso! Valor: R$ ${valorFrete.toFixed(2)}`,
  endereco_completo: item.endereco_formatado,
  rua: item.rua,
  numero: item.numero,
  bairro: item.bairro,
  cidade: item.cidade,
  estado: item.estado,
  valor_frete: valorFrete,
  distancia_km: distanciaKm,
  faixa_distancia: faixaDescricao,
  coordenadas: {
    cliente_lat: item.latitude,
    cliente_lng: item.longitude,
    origem_lat: item.origem_lat,
    origem_lng: item.origem_lng
  }
};
